import sqlite3
tabs = ['customers','orders','orders_archive','order_items','payments','addresses']
for db in ['databases/source.db','databases/target.db']:
    con = sqlite3.connect("file:%s?mode=ro" % db, uri=True)
    print("==", db)
    for t in tabs:
        try:
            n = con.execute('SELECT COUNT(*) FROM "%s"' % t).fetchone()[0]
        except Exception as e:
            n = "ERR %s" % e
        print("  %-15s %s" % (t, n))
    # any other tables/views present
    print("  all objects:", con.execute("select type,name from sqlite_master").fetchall())
    con.close()
EOF"}

